import { jsonLog } from '../../log.js';

export interface ExchangeResult {
  status: number;
  key: string;
}

export function logExchange(userId: string, result: ExchangeResult): void {
  jsonLog('openrouter.exchange', { userId, status: result.status, key: result.key });
}
